## Python3 코드

```python
num = 5

def g():
    print(num, end=" ")

def f():
    num = 9
    while num < 8:
        num += 1
    print(num, end=" ")
    g()

f()

print(num, end=" ")

```

## C 코드

```c
int num = 5;

void g() {
    printf("%d ", num);
}
void f() {  
    int num = 9;
    while(num < 8)
        num++;
    printf("%d ", num);
    g();
}

int main() {
    f();

    printf("%d", num);
    return 0;
}
```

